{
  "root": "root",
  "state": {},
  "elements": {
    "root": {
      "type": "Column",
      "props": {
        "style": {
          "padding": 16,
          "gap": 16
        }
      },
      "children": [
        "title",
        "intro_card",
        "modes_title",
        "option1_card",
        "option2_card",
        "option3_card",
        "quick_actions_title",
        "quick_actions_card"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Universal Scanner Activation",
        "style": {
          "typography": "headline-medium"
        }
      },
      "children": []
    },
    "intro_card": {
      "type": "Card",
      "props": {
        "style": {
          "padding": 16
        }
      },
      "children": [
        "intro_col"
      ]
    },
    "intro_col": {
      "type": "Column",
      "props": {
        "style": {
          "gap": 8
        }
      },
      "children": [
        "intro_title",
        "intro_text"
      ]
    },
    "intro_title": {
      "type": "Text",
      "props": {
        "text": "Scanning Environment and Permissions",
        "style": {
          "typography": "title-medium"
        }
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This response assumes the user is operating a mobile device with a functional rear-facing camera. It is assumed that \"linear barcodes\" refer to standard retail symbologies such as UPC-A, UPC-E, or EAN-13 used for product identification. Camera permissions must be granted to the browser or host application to enable video capture for decoding.",
        "style": {
          "typography": "body-medium"
        }
      },
      "children": []
    },
    "modes_title": {
      "type": "Text",
      "props": {
        "text": "Active Scanning Modes",
        "style": {
          "typography": "title-large"
        }
      },
      "children": []
    },
    "option1_card": {
      "type": "Card",
      "props": {
        "style": {
          "padding": 16
        }
      },
      "children": [
        "option1_col"
      ]
    },
    "option1_col": {
      "type": "Column",
      "props": {
        "style": {
          "gap": 12
        }
      },
      "children": [
        "option1_header",
        "option1_desc",
        "option1_button"
      ]
    },
    "option1_header": {
      "type": "Row",
      "props": {
        "style": {
          "gap": 16,
          "alignItems": "center"
        }
      },
      "children": [
        "option1_icon",
        "option1_title"
      ]
    },
    "option1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000090_01_3_upc-scan.svg",
        "style": {
          "size": 24
        }
      },
      "children": []
    },
    "option1_title": {
      "type": "Text",
      "props": {
        "text": "Web-Based Universal Scanner",
        "style": {
          "typography": "title-medium"
        }
      },
      "children": []
    },
    "option1_desc": {
      "type": "Text",
      "props": {
        "text": "Recognizes standard QR codes and linear barcodes via browser. Instant access without installation.",
        "style": {
          "typography": "body-medium"
        }
      },
      "children": []
    },
    "option1_button": {
      "type": "Button",
      "props": {
        "label": "Launch Web Scanner",
        "variant": "filled"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "url": "https://qrcodescan.in/"
        }
      }
    },
    "option2_card": {
      "type": "Card",
      "props": {
        "style": {
          "padding": 16
        }
      },
      "children": [
        "option2_col"
      ]
    },
    "option2_col": {
      "type": "Column",
      "props": {
        "style": {
          "gap": 12
        }
      },
      "children": [
        "option2_header",
        "option2_desc",
        "option2_button"
      ]
    },
    "option2_header": {
      "type": "Row",
      "props": {
        "style": {
          "gap": 16,
          "alignItems": "center"
        }
      },
      "children": [
        "option2_icon",
        "option2_title"
      ]
    },
    "option2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001502_01_3_bag-check.svg",
        "style": {
          "size": 24
        }
      },
      "children": []
    },
    "option2_title": {
      "type": "Text",
      "props": {
        "text": "Retail Price Search",
        "style": {
          "typography": "title-medium"
        }
      },
      "children": []
    },
    "option2_desc": {
      "type": "Text",
      "props": {
        "text": "Manual lookup or barcode entry for price comparison. Aggregated retail data.",
        "style": {
          "typography": "body-medium"
        }
      },
      "children": []
    },
    "option2_button": {
      "type": "Button",
      "props": {
        "label": "Check Prices",
        "variant": "filled"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "url": "https://shopping.google.com/"
        }
      }
    },
    "option3_card": {
      "type": "Card",
      "props": {
        "style": {
          "padding": 16
        }
      },
      "children": [
        "option3_col"
      ]
    },
    "option3_col": {
      "type": "Column",
      "props": {
        "style": {
          "gap": 12
        }
      },
      "children": [
        "option3_header",
        "option3_desc",
        "option3_button"
      ]
    },
    "option3_header": {
      "type": "Row",
      "props": {
        "style": {
          "gap": 16,
          "alignItems": "center"
        }
      },
      "children": [
        "option3_icon",
        "option3_title"
      ]
    },
    "option3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000175_01_1_camera.svg",
        "style": {
          "size": 24
        }
      },
      "children": []
    },
    "option3_title": {
      "type": "Text",
      "props": {
        "text": "Advanced Scanner Application",
        "style": {
          "typography": "title-medium"
        }
      },
      "children": []
    },
    "option3_desc": {
      "type": "Text",
      "props": {
        "text": "Dedicated tool for rapid batch scanning and history. Offline capability.",
        "style": {
          "typography": "body-medium"
        }
      },
      "children": []
    },
    "option3_button": {
      "type": "Button",
      "props": {
        "label": "Install Scanner App",
        "variant": "filled"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "url": "https://play.google.com/store/apps/details?id=com.google.zxing.client.android"
        }
      }
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "style": {
          "typography": "title-large"
        }
      },
      "children": []
    },
    "quick_actions_card": {
      "type": "Card",
      "props": {
        "style": {
          "padding": 16
        }
      },
      "children": [
        "quick_actions_col"
      ]
    },
    "quick_actions_col": {
      "type": "Column",
      "props": {
        "style": {
          "gap": 8
        }
      },
      "children": [
        "troubleshooting_button",
        "standards_button"
      ]
    },
    "troubleshooting_button": {
      "type": "Button",
      "props": {
        "label": "Troubleshooting Camera",
        "variant": "text"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "url": "https://support.google.com/android/answer/9334246?hl=en"
        }
      }
    },
    "standards_button": {
      "type": "Button",
      "props": {
        "label": "Barcode Standards Info",
        "variant": "text"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "url": "https://www.gs1.org/standards/barcodes"
        }
      }
    }
  }
}
